text:
{
  "design": {
    "theme": "playground",
    "picture_style": "photo"
  },
  "flow": [
    {
      "slide": 1,
      "does": "Recall familiar animal names",
      "look_at": {
        "kind": "picture",
        "shows": "Four familiar adult animals"
      },
      "teaches": []
    },
    {
      "slide": 2,
      "does": "Share the learning objectives",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": []
    },
    {
      "slide": 3,
      "does": "Name cows, calves, sheep and lambs",
      "look_at": {
        "kind": "picture",
        "shows": "Two adult animals beside their young"
      },
      "teaches": [1]
    },
    {
      "slide": 4,
      "does": "Name hens, chicks, dogs and puppies",
      "look_at": {
        "kind": "picture",
        "shows": "Two more adult animals beside their young"
      },
      "teaches": [1]
    },
    {
      "slide": 5,
      "does": "Model matching and naming an animal pair",
      "look_at": {
        "kind": "picture",
        "shows": "A hen beside a chick"
      },
      "teaches": [1]
    },
    {
      "slide": 6,
      "does": "Match and name the other three pairs",
      "look_at": {
        "kind": "picture",
        "shows": "Three adults and three young animals in mixed order"
      },
      "teaches": [1]
    },
    {
      "slide": 7,
      "does": "Teach how a chick grows into a hen",
      "look_at": {
        "kind": "picture-sequence",
        "shows": "A chick becomes bigger and develops adult feathers"
      },
      "teaches": [2]
    },
    {
      "slide": 8,
      "does": "Correct the idea that a chick is just a tiny hen",
      "look_at": {
        "kind": "picture",
        "shows": "Fluffy chick covering compared with adult hen feathers"
      },
      "teaches": [2]
    },
    {
      "slide": 9,
      "does": "Check understanding of both growth changes",
      "look_at": {
        "kind": "none",
        "shows": null
      },
      "teaches": [2]
    },
    {
      "slide": 10,
      "does": "Model describing two changes",
      "look_at": {
        "kind": "picture",
        "shows": "A small chick and a full-grown hen at the same scale"
      },
      "teaches": [2]
    },
    {
      "slide": 11,
      "does": "Describe the same changes independently",
      "look_at": {
        "kind": "picture",
        "shows": "Another chick and adult hen pair"
      },
      "teaches": [2]
    },
    {
      "slide": 12,
      "does": "Apply growth ideas to a partly grown chick",
      "look_at": {
        "kind": "picture",
        "shows": "A young female chicken with some adult feathers"
      },
      "teaches": [2]
    }
  ],
  "title": {
    "template": "title",
    "heading": "Animals and their young",
    "lead": "Name the animals you know.",
    "picture": {
      "shows": "Separate photographs of an adult cow, sheep, hen and dog",
      "must_see": [
        "adult dairy cow",
        "adult woolly sheep",
        "adult brown hen",
        "adult pet dog"
      ],
      "subject": "generic"
    }
  },
  "slides": [
    {
      "template": "compare",
      "heading": "Adults and their young",
      "columns": [
        {
          "label": "Cow and calf",
          "text": "A young cow is a calf.",
          "picture": {
            "shows": "An adult cow standing beside a small calf",
            "must_see": [
              "adult cow",
              "small calf"
            ],
            "subject": "generic"
          }
        },
        {
          "label": "Sheep and lamb",
          "text": "A young sheep is a lamb.",
          "picture": {
            "shows": "An adult sheep standing beside a small lamb",
            "must_see": [
              "adult sheep",
              "small lamb"
            ],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "compare",
      "heading": "More adults and young",
      "columns": [
        {
          "label": "Hen and chick",
          "text": "A hen is an adult female chicken.",
          "picture": {
            "shows": "An adult hen beside a newly hatched chick",
            "must_see": [
              "adult hen",
              "small fluffy chick"
            ],
            "subject": "generic"
          }
        },
        {
          "label": "Dog and puppy",
          "text": "A young dog is a puppy.",
          "picture": {
            "shows": "An adult dog beside a puppy of the same breed",
            "must_see": [
              "adult dog",
              "small puppy"
            ],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "visual-text",
      "heading": "Watch a match",
      "lead": "I match the hen to the chick.",
      "points": [
        "The hen is the adult.",
        "The chick is the young chicken."
      ],
      "figure": {
        "shows": "A hen and a chick shown clearly side by side",
        "must_see": [
          "adult hen",
          "fluffy young chick"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "practice",
      "heading": "Make the matches",
      "questions": [
        "Match the cow to its young. Name both.",
        "Match the sheep to its young. Name both.",
        "Match the dog to its young. Name both."
      ],
      "instruction": "Point to each pair and say the names.",
      "picture": {
        "shows": "Six separate animal photographs: cow, sheep and dog across the top; puppy, calf and lamb across the bottom, with no connecting lines",
        "must_see": [
          "adult cow",
          "adult sheep",
          "adult dog",
          "small puppy below cow position"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "picture-sequence",
      "heading": "A chick grows into a hen",
      "sequence": [
        {
          "shows": "A newly hatched female chick with fluffy down, before adult feathers develop; shown at a consistent scale with later stages",
          "must_see": [
            "small yellow chick",
            "soft fluffy covering"
          ],
          "subject": "generic",
          "caption": "Small and fluffy"
        },
        {
          "shows": "An older female chick, bigger than the first chick, with developing wing feathers but not yet a full adult body or plumage",
          "must_see": [
            "larger young chicken",
            "developing wing feathers",
            "remaining fluffy patches"
          ],
          "subject": "generic",
          "caption": "Bigger; feathers grow"
        },
        {
          "shows": "A fully grown hen, larger than both earlier stages, with complete adult plumage",
          "must_see": [
            "full grown hen",
            "adult wing feathers",
            "adult tail feathers"
          ],
          "subject": "generic",
          "caption": "Adult hen"
        }
      ]
    },
    {
      "template": "compare",
      "heading": "Not just a tiny hen",
      "columns": [
        {
          "label": "Chick",
          "text": "Soft, fluffy down covers its body.",
          "picture": {
            "shows": "A close view of a newly hatched chick showing its fluffy down",
            "must_see": [
              "fluffy chick body",
              "short soft down"
            ],
            "subject": "generic"
          }
        },
        {
          "label": "Hen",
          "text": "It has grown adult feathers too.",
          "picture": {
            "shows": "A close view of an adult hen showing shaped wing and tail feathers",
            "must_see": [
              "layered wing feathers",
              "long tail feathers"
            ],
            "subject": "generic"
          }
        }
      ]
    },
    {
      "template": "hinge",
      "heading": "Choose an answer",
      "stem": "What changes as a chick grows into a hen?",
      "options": [
        "Only its size",
        "Only its feathers",
        "Its size and feathers"
      ],
      "correct": 3
    },
    {
      "template": "visual-text",
      "heading": "Watch me describe",
      "lead": "I can describe two changes.",
      "points": [
        "The chick gets bigger.",
        "It grows adult feathers."
      ],
      "figure": {
        "shows": "A small newly hatched female chick beside an adult hen, photographed at the same scale",
        "must_see": [
          "small fluffy chick",
          "much larger hen",
          "adult wing feathers"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "practice",
      "heading": "Describe the changes",
      "questions": [
        "How does its size change?",
        "How does its feather covering change?"
      ],
      "instruction": "Say two changes from chick to hen.",
      "picture": {
        "shows": "A different newly hatched female chick and a fully grown hen side by side at the same scale",
        "must_see": [
          "small fluffy chick",
          "large adult hen",
          "long adult feathers"
        ],
        "subject": "generic"
      }
    },
    {
      "template": "question-set",
      "heading": "Still growing",
      "questions": [
        "What shows that this chick has started to change?",
        "What will change as it grows into a hen?"
      ],
      "instruction": "Look closely. Explain your ideas.",
      "picture": {
        "shows": "A partly grown female chick with distinct wing feathers and remaining down on its head and body, not yet an adult hen",
        "must_see": [
          "partly grown chick",
          "visible wing feathers",
          "fluffy head covering",
          "short developing tail"
        ],
        "subject": "generic"
      }
    }
  ]
}
